parameters.jsCode:
// Saca el JSON de la correccion sin fiarse de que venga limpio.
const salida = [];
for (const item of $input.all()) {
  const entrega = $('Normalizar entrega').first().json;
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let datos;
  try {
    datos = JSON.parse(bruto);
  } catch (error) {
    datos = { criterios: [], nota: 0, apto_propuesto: false, comentario_alumno: '', revisar_humano: 'correccion no parseable: ' + bruto.slice(0, 200) };
  }
  salida.push({
    json: {
      ...entrega,
      nota_ia: Number(datos.nota ?? 0),
      criterios: JSON.stringify(datos.criterios ?? []),
      comentario: datos.comentario_alumno ?? '',
      revisar_humano: datos.revisar_humano ?? '',
      apto_propuesto: Boolean(datos.apto_propuesto),
      estado: 'corregida_ia',
    },
  });
}
return salida;

